/// <reference types="node" />

declare const crypto: {
  subtle: {
    importKey: (format: string, keyData: any, algorithm: any, extractable: boolean, keyUsages: string[]) => Promise<any>
    sign: (algorithm: string, key: any, data: any) => Promise<ArrayBuffer>
  }
}

export interface ConnectorConfig {
  shopifySecret: string
  slackBotToken: string
  slackChannel: string
  shopifyHmacHeader: string
  rawBody: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPayload {
  id: number
  name: string
  email: string
  total_price: string
  line_items: Array<{ title: string; quantity: number }>
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

async function verifyHmac(secret: string, rawBody: string, hmacHeader: string): Promise<boolean> {
  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const messageData = encoder.encode(rawBody)

  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )

  const signature = await crypto.subtle.sign('HMAC', cryptoKey, messageData)
  const signatureBase64 = Buffer.from(signature).toString('base64')

  return signatureBase64 === hmacHeader
}

function formatLineItems(lineItems: Array<{ title: string; quantity: number }>): string {
  return lineItems.map((item) => `${item.title} x${item.quantity}`).join(', ')
}

function formatMessage(payload: ShopifyOrderPayload): string {
  const lineItemsSummary = formatLineItems(payload.line_items)
  return `New order ${payload.name} from ${payload.email} for $${payload.total_price}: ${lineItemsSummary}`
}

export async function handle(payload: ShopifyOrderPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (payload.id === undefined || payload.id === null) throw new Error('Missing required field: id')
  if (!payload.name) throw new Error('Missing required field: name')
  if (!payload.email) throw new Error('Missing required field: email')
  if (!payload.total_price) throw new Error('Missing required field: total_price')
  if (!payload.line_items || !Array.isArray(payload.line_items)) throw new Error('Missing required field: line_items')

  if (!config.shopifySecret) throw new Error('Missing config: shopifySecret')
  if (!config.slackBotToken) throw new Error('Missing config: slackBotToken')
  if (!config.slackChannel) throw new Error('Missing config: slackChannel')
  if (!config.shopifyHmacHeader) throw new Error('Missing config: shopifyHmacHeader')
  if (!config.rawBody) throw new Error('Missing config: rawBody')

  const fetch = config.fetch ?? globalThis.fetch

  const isValid = await verifyHmac(config.shopifySecret, config.rawBody, config.shopifyHmacHeader)
  if (!isValid) {
    throw new Error('Invalid HMAC signature')
  }

  const text = formatMessage(payload)

  const response = await fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text
    })
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  const result = (await response.json()) as { ok: boolean; channel: string; ts: string }

  return {
    slackMessageTs: result.ts,
    slackChannel: result.channel
  }
}

